interface Property { boolean test(int x); }
class CheckArray {
    static boolean check(int[] a, Property p) {
        for (int i = 0; i < a.length; ++i) {
            if (p.test(a[i])) return true;
        }
        return false;
    }
}

interface Property { boolean test(int value); }
class Demo {
    static boolean check(int[] values, Property p) {
        for (int i = 0; i < values.length; ++i) {
            if (p.test(values[i])) return true;
        }
        return false;
    }
    public static void main(String[] args) {
        int[] values = {2, 4, 6};
        Property p = value -> value % 2 != 0;
        System.out.println(check(values, p));
    }
}

interface Property { boolean test(Object r); }
class Demo {
    static int calls = 0;
    static boolean check(Object[] a, Property p) {
        for (int i = 0; i < a.length; ++i) {
            calls++;
            if (p.test(a[i])) return true;
        }
        return false;
    }
    public static void main(String[] args) {
        Property p = r -> ((Integer) r) % 2 == 0;
        Object[] a = {3, 8, 10};
        check(a, p);
        System.out.println(calls);
    }
}

abstract class Base {
    protected int x;
    Base(int x) { this.x = x; }
    abstract int value();
}
class Demo {
    public static void main(String[] args) {
        Base item = new Base(7) {
            int value() { return x * 3; }
        };
        System.out.println(item.value());
    }
}

interface Property { boolean test(Object r); }
class Demo {
    static Property matching(String word) {
        return new Property() {
            public boolean test(Object r) { return word.equals(r); }
        };
    }
    public static void main(String[] args) {
        Property p = matching("DS");
        System.out.print(p.test("DS") + " ");
        System.out.println(p.test("ERA"));
    }
}

interface Property {
    boolean test(Object r);
    default boolean rejects(Object r) { return !test(r); }
}
class Demo {
    public static void main(String[] args) {
        Property p = r -> ((String) r).startsWith("A");
        System.out.print(p.rejects("Bee") + " ");
        System.out.println(p.rejects("Apple"));
    }
}

interface Property { boolean test(Object r); }
class Demo {
    Property anonymous() {
        return new Property() {
            public boolean test(Object r) { return this == r; }
        };
    }
    Property lambda() { return r -> this == r; }
    public static void main(String[] args) {
        Demo owner = new Demo();
        Property anonymous = owner.anonymous();
        Property lambda = owner.lambda();
        System.out.print(anonymous.test(anonymous) + " ");
        System.out.print(lambda.test(owner) + " ");
        System.out.print(anonymous.test(owner) + " ");
        System.out.println(lambda.test(lambda));
    }
}

interface Property { boolean test(Object r); }
